      "evidence": {
        "quote": "Cooked eggs keep in the fridge for up to a week",
        "critique_and_reasoning": "The one-week timeline applies to fully firm eggs, whereas soft or jammy eggs have higher moisture and shorter shelf life."
      },
      "findingType": "safe_handling",
      "severity": "medium",
